// <auto-generated> by cs/tools/ts2cs.mjs from src/sim/timeline.ts, then fixed by hand where it says so.
// The world winding down: the mains, and things that happen out there.
//
//   the mains    a generated world starts with the water and the power still on. Each goes off
//                for good on a day rolled from the seed (rollTimeline), sooner the further on
//                the world is (settings.progression: weeks, months, a year, years; a year on,
//                they're off from the start). Hand-made maps have no mains.
//     water on   kitchen counters, toilets and baths are taps: clean water (water.ts).
//     power on   iceboxes keep food like fridges (power.ts spoilage), and indoors is lit at
//                night (inLight: guards hit harder, you see as far as by day: sight.ts).
//   happenings   while the world is still winding down (until a few days after the power goes):
//     helicopter on a rolled day a helicopter comes over, hangs over you (the one you control,
//                else the first survivor) for HELI_HOVER ticks, then flies off, thundering
//                (noise 'helicopter') every HELI_NOISE_EVERY ticks: it drags the dead after it.
//     alarms     smash a window into a building while the power's on and its alarm may go off
//                (ALARM_CHANCE), ringing (noise 'alarm') for ALARM_TICKS.
//     far off    now and then, on the hour, gunshots or a scream somewhere FAR_MIN..FAR_MAX
//                tiles away: real noise, which moves the dead out there.
// Rolls use hash.ts (seed and tick), not the sim RNG.
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class TimelineMod
{
    static TimelineMod()
    {
        Time.onClock(() => ALARM_TICKS = Time.TICKS_PER_HOUR);
    }

    /// <summary>[earliest, latest] day the water goes, the power goes, and the helicopter comes, by progression.</summary>
    public static readonly List<WINDOWS> WINDOWS = [new() { water = [8, 14], power = [10, 18], heli = [3, 6] }, new() { water = [3, 7], power = [4, 9], heli = [2, 5] }, new() { water = [0, 0], power = [0, 0], heli = [0, 0] }, new() { water = [0, 0], power = [0, 0], heli = [0, 0] }];

    public const int HELI_HOVER = 300;

    public const int HELI_NOISE_EVERY = 30;

    /// <summary>Ticks per tile the helicopter flies.</summary>
    public const int HELI_STEP = 2;

    public const double ALARM_CHANCE = 0.5;

    public static double ALARM_TICKS = Time.TICKS_PER_HOUR;

    /// <summary>Chance, each hour while the world winds down, of something heard far off.</summary>
    public const double FAR_CHANCE = 0.06;

    public const int FAR_MIN = 25;

    public const int FAR_MAX = 45;

    /// <summary>Happenings go on until this many days after the power goes.</summary>
    public const int WIND_DOWN_DAYS = 3;

    /// <summary>Looks that are taps while the water's on.</summary>
    public static readonly List<string> TAP_LOOKS = ["counter", "sink", "toilet", "bath"];

    /// <summary>Drinks still in a toilet's tank or a bath once the mains are off (lots.ts fills them as the house is made).</summary>
    public static readonly JsRecord<double> TANK_WATER = new() { ["toilet"] = 2, ["bath"] = 4 };

    /// <summary>Sets the days the mains go off and the helicopter comes (generated worlds).</summary>
    public static void rollTimeline(SimState state, double seed)
    {
        var w = Js.NN(WINDOWS[Js.Idx(JsMath.max(0, JsMath.min(WINDOWS.length - 1, state.settings.progression)))]);
        double roll(List<double> __p0, double key)
        {
            var (lo, hi) = __p0;
            return (hi == 0) ? 0 : (lo + JsMath.floor(Hash.hashRoll(seed, key) * ((hi - lo) + 1)));
        };
        state.timeline = new Timeline { waterOffDay = roll(w.water, 31358.0), powerOffDay = roll(w.power, 0x9077), helicopterDay = roll(w.heli, 19985.0), heli = null, alarms = [] };
    }

    public static bool waterOn(SimState state)
    {
        return (state.timeline != null) && (Time.dayOf(state.tick) < state.timeline.waterOffDay);
    }

    public static bool powerOn(SimState state)
    {
        return (state.timeline != null) && (Time.dayOf(state.tick) < state.timeline.powerOffDay);
    }

    /// <summary>Is this a tap with water coming out of it?</summary>
    public static bool isTap(SimState state, Furniture f)
    {
        return Js.T(((f.look != null) && TAP_LOOKS.includes(f.look)) && Js.T(waterOn(state)));
    }

    /// <summary>Does this keep food cold (an icebox with the power on)?</summary>
    public static bool isMainsFridge(SimState state, Furniture f)
    {
        return Js.T((f.look == "icebox") && Js.T(powerOn(state)));
    }

    /// <summary>Indoors at night with the power on: the lights are on.</summary>
    public static bool mainsLit(SimState state, Point p)
    {
        return (Js.T((Js.T(Js.T(Time.isNight(state.tick)) && Js.T(powerOn(state)))) && Js.T(Grids.inBounds(state.grid, p.x, p.y)))) && (Rooms.labelAt(state, p.x, p.y) != Rooms.OUTDOORS);
    }

    /// <summary>Who the world's happenings come looking for: the one you control, else the first survivor.</summary>
    public static Point? focus(SimState state)
    {
        var you = Js.T(state.control) ? state.survivors.find((s) => s.id == Js.NN(state.control).survivorId) : null;
        return (you ?? state.survivors[Js.Idx(0)])?.pos ?? null;
    }

    /// <summary>A point `r` tiles from `p` in the direction `a` (radians), on the map.</summary>
    public static Point off(SimState state, Point p, double a, double r)
    {
        var __d1 = state.grid;
        var width = __d1.width;
        var height = __d1.height;
        return new Point { x = Js.I(JsMath.max(0, JsMath.min(width - 1, JsMath.round(p.x + (JsMath.cos(a) * r))))), y = Js.I(JsMath.max(0, JsMath.min(height - 1, JsMath.round(p.y + (JsMath.sin(a) * r))))) };
    }

    /// <summary>Which way, in words, from a to b.</summary>
    public static string compass(Point a, Point b)
    {
        var dx = b.x - a.x;
        var dy = b.y - a.y;
        var ns = ((JsMath.abs(dy) * 2) > JsMath.abs(dx)) ? ((dy < 0) ? "north" : "south") : "";
        var ew = ((JsMath.abs(dx) * 2) > JsMath.abs(dy)) ? ((dx < 0) ? "west" : "east") : "";
        return (Js.T(Js.T(ns) && Js.T(ew))) ? $"{Js.Str(ns)}-{Js.Str(ew)}" : (Js.Or(Js.Or(ns, ew), "nearby"));
    }

    /// <summary>Ring an alarm (a window smashed into a building while the power's on, maybe).</summary>
    public static void maybeAlarm(SimState state, Point p, double key)
    {
        var t = state.timeline;
        if ((!Js.T(t) || !Js.T(powerOn(state))) || (Hash.hashRoll(key, state.tick, 0xa1a) >= ALARM_CHANCE))
        {
            return;
        }
        t.alarms.push(new() { x = Js.I(p.x), y = Js.I(p.y), untilTick = state.tick + ALARM_TICKS });
        Events.logEvent(state, $"An alarm went off at ({Js.Str(p.x)}, {Js.Str(p.y)})!");
        Noise.makeNoise(state, p, "alarm");
    }

    /// <summary>Every tick: the mains going off, the helicopter, alarms, noises far off.</summary>
    public static void updateTimeline(SimState state)
    {
        var t = state.timeline;
        if (!Js.T(t))
        {
            return;
        }
        var day = Time.dayOf(state.tick);
        if ((Time.tickOfDay(state.tick) == 0) && (state.tick > 0))
        {
            if (day == t.waterOffDay)
            {
                Events.logEvent(state, "The taps ran dry: the water has been shut off.");
            }
            if (day == t.powerOffDay)
            {
                Events.logEvent(state, "The lights went out: the power is off for good.");
            }
            if (day > t.powerOffDay)
            {
                foreach (var f in Js.Iter(FurnitureMod.ofKind(state, "crate")))
                {
                    if ((f.look == "icebox") && (f.loot > 0))
                    {
                        f.loot -= 1;
                    }
                }
            }
        }
        t.alarms = t.alarms.filter((a) => state.tick < a.untilTick);
        if ((state.tick % 20) == 0)
        {
            foreach (var a in Js.Iter(t.alarms))
            {
                Noise.makeNoise(state, a, "alarm");
            }
        }
        updateHeli(state, t);
        var winding = (t.powerOffDay > 0) && (day < (t.powerOffDay + WIND_DOWN_DAYS));
        var you = focus(state);
        if (((Js.T(Js.T(winding) && Js.T(you))) && ((state.tick % Time.TICKS_PER_HOUR) == 0)) && (Hash.hashRoll(Js.Q(state.world?.seed, 0), state.tick, 0xfa2) < FAR_CHANCE))
        {
            var a = (Hash.hashRoll(state.tick, 0xfa3) * JsMath.PI) * 2;
            var at = off(state, you, a, FAR_MIN + JsMath.floor(Hash.hashRoll(state.tick, 0xfa4) * ((FAR_MAX - FAR_MIN) + 1)));
            var shots = Hash.hashRoll(state.tick, 0xfa5) < 0.6;
            Noise.makeNoise(state, at, Js.T(shots) ? "gunfire" : "scream");
            Events.logEvent(state, $"{Js.Str(Js.T(shots) ? "Gunshots" : "A scream")}, far off to the {Js.Str(compass(you, at))}.");
        }
    }

    public static void updateHeli(SimState state, Timeline t)
    {
        var you = focus(state);
        if (!Js.T(t.heli))
        {
            if (((t.helicopterDay == 0) || (Time.dayOf(state.tick) != t.helicopterDay)) || !Js.T(you))
            {
                return;
            }
            if (Time.tickOfDay(state.tick) != JsMath.floor(Time.DAY_LENGTH * 0.6))
            {
                return;
            }
            var a = (Hash.hashRoll(Js.Q(state.world?.seed, 0), 19986.0) * JsMath.PI) * 2;
            var from = off(state, you, a, 60);
            var exit = off(state, you, a + JsMath.PI, 80);
            t.heli = new TimelineHeli { x = Js.I(from.x), y = Js.I(from.y), leaveTick = (state.tick + HELI_HOVER) + (60 * HELI_STEP), exit = exit };
            Events.logEvent(state, $"A helicopter, coming in from the {Js.Str(compass(you, from))}...");
            return;
        }
        var h = t.heli;
        var leaving = state.tick >= h.leaveTick;
        var goal = Js.T(leaving) ? h.exit : (you ?? h.exit);
        if ((state.tick % HELI_STEP) == 0)
        {
            h.x += JsMath.sign(goal.x - h.x);
            h.y += JsMath.sign(goal.y - h.y);
        }
        if ((state.tick % HELI_NOISE_EVERY) == 0)
        {
            Noise.makeNoise(state, h, "helicopter");
        }
        if ((Js.T(leaving) && (h.x == h.exit.x)) && (h.y == h.exit.y))
        {
            t.heli = null;
            t.helicopterDay = 0;
            Events.logEvent(state, "The helicopter is gone. The dead it drew are not.");
        }
    }
}
